import { mapAndValidate } from '../parsing-and-validation/map-and-validate/map-and-validate';

export interface ISkinsCatalogue {
    [key: string]: ISkinsCatalogueEntry;
}

export interface ISkinsCatalogueEntry {
    [key: string]: string;
}

export class SkinCatalogueService {
    private map: ISkinsCatalogue;

    private keys: string[];

    constructor(skinMap: ISkinsCatalogue) {
        this.parseMap(skinMap);
    }

    public getSkinsByGameName(gameName: string): ISkinsCatalogueEntry {
        if (this.keys.indexOf(gameName) === -1) {
            throw new Error(`getSkinsByGameName: ${gameName} not included in skin map`);
        }

        return this.map[gameName];
    }

    public getTranslatedSkinName(skinName: string): string {
        for (const game in this.map) {
            if (this.map[game][skinName]) {
                return this.map[game][skinName];
            }
        }
        throw new Error(`getTranslatedSkinName: ${skinName} not found in any of the games in the skin map`);
    }

    public getGameNameFromSkinName(skinName: string): string {
        for (const key of this.keys) {
            if (this.map[key][skinName]) {
                return key;
            }
        }
        throw new Error(`getGameNameFromSkinName: No Game found that includes ${skinName}`);
    }

    public skinExistsInGame(gameName: string, skinName: string): boolean {
        const activeSkins = this.getSkinsByGameName(gameName);
        return Object.keys(activeSkins).indexOf(skinName) > -1;
    }

    private parseMap(map: ISkinsCatalogue): void {
        const parsedMap: ISkinsCatalogue = {};
        mapAndValidate(map, parsedMap);
        this.map = map;
        this.keys = Object.keys(this.map);
    }
}
